svg.metadata:
{
  "version": 1,
  "initial": {
    "mode": "static",
    "description": "Original illustrated gaze"
  },
  "head": {
    "target": "_03-·-Head---complete-skull",
    "pivot": [
      670,
      710
    ]
  },
  "dynamicEyes": {
    "left": "iris-dynamic-left",
    "right": "iris-dynamic-right",
    "neutralCenters": {
      "left": [
        530,
        607
      ],
      "right": [
        815,
        510
      ]
    },
    "normalRadii": {
      "left": 58,
      "right": 52
    }
  },
  "selectMode": "Keep iris-static-{side} visible and iris-dynamic-{side} plus eye-dynamic-rim-{side} hidden for the original drawing. For tracking, hide iris-static-{side}, show iris-dynamic-{side} and eye-dynamic-rim-{side}, for both eyes.",
  "masking": "The one eye-opening-{side} path drives the dark socket fill, iris clip, and 16-unit dark outline drawn above the red circle. Keep clip and outline fixed when moving iris-gaze-{side}. The continuous outline masks the top and bottom edges, leaving a dark band before the white skull. No separate lower lid is needed.",
  "gazeGuides": {
    "group": "eye-gaze-guides",
    "boundary": "gaze-bounds-{side}",
    "neutral": "gaze-neutral-{side}",
    "downLimit": "gaze-down-limit-{side}",
    "maxHorizontal": 24,
    "maxUp": 12,
    "maxDown": {
      "left": 85.56,
      "right": 104.56
    },
    "coordinateSpace": "head group local coordinates",
    "mapping": "Convert pointer position into head coordinates. Clamp one normalized vector (u,v) to the unit disk. For each eye set dx=24*u and dy=(v<0?12:maxDownForThisEye)*v. Translate only iris-gaze-{side}. The two eyes share the vector, while each has its own downward limit."
  },
  "downCalibration": {
    "pose": "unchanged original socket shape in dynamic mode",
    "horizontalOffset": 0,
    "visibleRedHeightFraction": 0.3,
    "measurement": "Vertical span of rendered red after clip and outline divided by full circle diameter; not area.",
    "maxDownMeasured": {
      "left": 85.56,
      "right": 104.56
    }
  },
  "notes": "No sleepy eyelid closing guides, pose morphs, runtime script, or animation are included. All bones, hands, controller, skull, brows and illustrated eye shapes remain unchanged."
}
